function formatOperationError(code:unknown,module:string,status:number){
 const key=typeof code==="string"?code:"UNKNOWN_ERROR";
 const language=typeof document==="undefined"?"ar":document.documentElement.lang.toLowerCase();
 const index=language.startsWith("fr")?2:language.startsWith("en")?1:0;
 const fieldKey=key.replace(/^(INVALID_|REQUIRED_)/,"");
 const field=resourceModules[module]?.fields.find(f=>f.key===fieldKey);
 const messages=translatedErrors[key];
 const fallback: [string,string,string]=key.startsWith("REQUIRED_")?["حقل مطلوب","Required field","Champ obligatoire"]:key.startsWith("INVALID_")?["قيمة غير صحيحة","Invalid value","Valeur invalide"]:["تعذر إتمام العملية","Operation failed","Échec de l’opération"];
 const fieldName=field?.label?uiText(field.label,index===1?"en":index===2?"fr":"ar")+": ":"";
 return (messages?.[index]??(operationLabels[key]&&index===0?operationLabels[key]:fieldName+fallback[index]));
}
export async function operationApi(tenantId:string,module:string,method="GET",body?:unknown,branch?:string,extra?:Record<string,string>){
 const query=new URLSearchParams({...extra,...(branch?{branch}:{})}).toString();
 const response=await fetch("/api/restaurant/operations/"+module+(query?"?"+query:""),{method,headers:{"content-type":"application/json","x-foon-tenant":tenantId,...((branch||(body&&typeof body==="object"&&"branchId" in body&&typeof body.branchId==="string"?body.branchId:""))?{"x-foon-branch":String(branch||(body as {branchId?:string}).branchId)}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});
 const result=await response.json().catch(()=>({}));
 if(!response.ok)throw Error(formatOperationError(result.code,module,response.status)+(result.incidentId?(typeof document!=="undefined"&&document.documentElement.lang==="en"?" · Reference: ":typeof document!=="undefined"&&document.documentElement.lang==="fr"?" · Référence : ":" · رمز التتبع: ")+String(result.incidentId):""));
 return result;
}
