 async function addTablesBulk(){
  if(busy)return;
  if(!Number.isInteger(bulkStart)||bulkStart<1||!Number.isInteger(bulkCount)||bulkCount<1||bulkCount>50||!Number.isInteger(bulkCapacity)||bulkCapacity<1||bulkCapacity>100){setMessage("تحقق من الأرقام: حتى 50 طاولة في الدفعة، وسعة من 1 إلى 100.");return;}
  if(!bulkSection){setMessage(translateUi("اختر قسم الصالة قبل إضافة الطاولات."));return;}
  const selectedBranch=bulkBranch||branch||null;
  if(selectedBranch&&!branches.some(b=>b.id===selectedBranch)){setMessage(translateUi("الفرع غير صالح."));return;}
  setBusy(true);setMessage("");
  let created=0;let failure="";
  try{
   for(let index=0;index<bulkCount;index++){
    const number=bulkStart+index;
    try{
     await operationApi(tenantId,"tables","POST",{name:String(number),status:"available",branchId:selectedBranch,data:{sectionId:bulkSection,number,capacity:bulkCapacity}});
     created++;
    }catch(error){failure=error instanceof Error?error.message:translateUi("تعذر إضافة الطاولة")+" "+number;break;}
   }
   await refresh();onChanged?.();
   if(created===bulkCount){setBulkOpen(false);setMessage(translateUi("تمت إضافة")+" "+created+" "+translateUi("طاولة بنجاح."));}
   else setMessage(translateUi("تمت إضافة")+" "+created+" "+translateUi("من")+" "+bulkCount+" طاولة. توقف الإجراء عند الخطأ: "+failure+" — تحقق من الأرقام الموجودة ثم أعد المحاولة.");
  }catch(error){setMessage(translateUi("تعذر تحديث القائمة:")+" "+String(error));}
  finally{setBusy(false);}
 }
